insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-000000000025', 'en', null, 'World Religions', 'An academic, comparative survey of the world''s major religious traditions — how scholars study them and what each teaches about the human condition. Built from openly-licensed OER Commons material (CC BY); the course describes beliefs neutrally without endorsing or disparaging any tradition.', null, 'foundations', 37, true, 'science', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-000000000025', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"The academic study of religion aims primarily to…","options":["prove which religion is true","describe and understand traditions on their own terms","convert readers to a faith","rank religions by age"],"answer":1,"explanation":"Religious studies describes and explains; it does not judge truth claims — see ''Studying religion academically''."},{"prompt":"A tradition centered on the Vedas, dharma, and rebirth is…","options":["Christianity","Hinduism","Shinto","Islam"],"answer":1,"explanation":"Hinduism is a Dharmic tradition — see ''The Dharmic religions''."},{"prompt":"Judaism, Christianity, and Islam are called Abrahamic because they…","options":["began in Europe","share the figure of Abraham","reject all scripture","worship many gods"],"answer":1,"explanation":"All three trace lineage to Abraham — see ''The Abrahamic religions''."},{"prompt":"The Buddhist path is organized around the…","options":["Ten Commandments","Four Noble Truths","Five Pillars","Analects"],"answer":1,"explanation":"The Four Noble Truths frame Buddhist teaching — see ''The Dharmic religions''."},{"prompt":"Many Indigenous traditions are best described as…","options":["identical worldwide","oral, local, and tied to land and community","based on a single global text","recently invented"],"answer":1,"explanation":"Indigenous traditions are typically oral and place-based — see ''Indigenous and ancient traditions''."},{"prompt":"Daoism and Confucianism both originated in…","options":["ancient India","ancient China","the Arabian Peninsula","Japan"],"answer":1,"explanation":"Both are East Asian traditions from China — see ''East Asian traditions''."},{"prompt":"''Monotheism'' means belief in…","options":["many gods","no gods","one God","nature spirits only"],"answer":2,"explanation":"Mono- (one) + theos (god) — see ''Studying religion academically''."},{"prompt":"A society where religion has less public authority is often called…","options":["pluralist","secular","orthodox","monastic"],"answer":1,"explanation":"Secularization describes religion''s reduced public role — see the applied project on the modern world."}]}'::jsonb, null, 10),
  (2, 'Studying religion academically', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what the academic study of religion is and name a few methods scholars use. Warm-up: from the diagnostic, what is the main goal of religious studies — to prove a faith, or to understand it?"},{"heading":"The idea","text":"Religion is hard to define because traditions vary so widely, but scholars usually point to a shared cluster: beliefs about what is sacred or ultimate, practices and rituals, ethical guidance, community, and often stories or scriptures. Religious studies is *descriptive*, not *devotional*: it asks what people believe and why, using tools like history, textual analysis, anthropology (fieldwork among living communities), and comparison. A useful distinction is the *emic* view (how insiders describe their own tradition) versus the *etic* view (how an outside analyst describes it). Both matter, and a careful scholar keeps them clearly labeled."},{"heading":"Worked example","text":"Take the word ''God''. In Islam and Judaism it names a single, transcendent creator (strict monotheism). In some forms of Hinduism, one ultimate reality (Brahman) is expressed through many deities (often described as non-dual or henotheistic). In many Indigenous traditions, the sacred is woven into land, ancestors, and specific places rather than a single supreme being. Same English word, very different concepts — which is exactly why scholars translate carefully and avoid assuming one framework fits all."},{"heading":"Your turn","text":"Emic or etic? (1) A Buddhist monk explaining meditation as he practices it. (2) A sociologist charting attendance across a city. (3) A believer reciting a creed. (4) An anthropologist comparing pilgrimage in two cultures. Answers: (1) emic, (2) etic, (3) emic, (4) etic."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming every religion has one holy book and one God — many do not. Mistake: treating the academic stance as hostility; describing a belief neutrally is not attacking it. Exit: (a) What word means ''belief in one God''? (b) Insider viewpoint: emic or etic? Answers: monotheism; emic."}]}'::jsonb, 'Describe, don''t judge: the academic study of religion reports what people believe and do, without ruling on whether it is true.', 12),
  (3, 'Indigenous and ancient traditions', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe common features scholars observe across Indigenous and ancient traditions, while respecting their diversity. Warm-up: are these traditions usually organized around a single global text?"},{"heading":"The idea","text":"Long before the large scriptural religions, human communities everywhere developed ways of relating to the sacred. Indigenous traditions — from the Americas, Africa, Australia, the Pacific, and beyond — are enormously diverse, but scholars often notice recurring features: they are typically *oral* (passed on by story and ceremony rather than a fixed book), *local* (tied to specific land, ancestors, and community), and integrated into daily life rather than set apart. Ancient traditions of Egypt, Mesopotamia, Greece, and Rome were often *polytheistic*, honoring many deities linked to natural and social forces. These traditions are not ''primitive'' precursors; many are living faiths practiced today."},{"heading":"Worked example","text":"Compare how the sacred is located. In many Aboriginal Australian traditions, ancestral beings shaped the land during the Dreaming, so particular sites carry ongoing sacred meaning. In ancient Greek religion, gods like Zeus and Athena were honored at temples through sacrifice and festival. In several West African traditions, a high creator god is acknowledged alongside intermediary spirits and revered ancestors. Different structures, but each maps the sacred onto place, community, and relationship."},{"heading":"Your turn","text":"Match the feature to the label — oral transmission, polytheism, place-based sacredness, ancestor veneration: (1) honoring many gods at temples, (2) knowledge carried by elders in story and song, (3) a specific mountain treated as holy, (4) rituals maintaining bonds with the deceased. Answers: (1) polytheism, (2) oral transmission, (3) place-based sacredness, (4) ancestor veneration."},{"heading":"Common mistakes & exit ticket","text":"Mistake: calling Indigenous traditions ''extinct'' — many continue today. Mistake: assuming they are all the same; they differ profoundly by region and people. Exit: (a) ''Many gods'' in one word? (b) Name one common way these traditions are transmitted. Answers: polytheism; orally (story/ceremony)."}]}'::jsonb, '''Indigenous religions'' is an umbrella term for thousands of distinct traditions — resist lumping them into one.', 12),
  (4, 'The Dharmic religions: Hinduism and Buddhism', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Outline core ideas of Hinduism and Buddhism and how they relate. Warm-up: which set of teachings — the Four Noble Truths or the Ten Commandments — organizes Buddhist practice?"},{"heading":"The idea","text":"The Dharmic traditions arose in the Indian subcontinent and share a family of concepts while differing sharply on others. *Hinduism* is a vast, ancient family of traditions drawing on scriptures like the Vedas and Upanishads; common threads include *dharma* (duty and cosmic order), *karma* (action and its consequences), *samsara* (the cycle of rebirth), and *moksha* (liberation from that cycle). *Buddhism*, founded on the teaching of Siddhartha Gautama (the Buddha), keeps karma and rebirth but reframes the goal: the *Four Noble Truths* diagnose suffering (dukkha), its cause (craving), its cessation, and the *Eightfold Path* leading there, culminating in *nirvana*. Notably, Buddhism generally does not center on a creator God."},{"heading":"Worked example","text":"Compare the aim of the spiritual life. In much of Hinduism, moksha is release of the self (atman) into or toward ultimate reality (Brahman). In Buddhism, the teaching of *anatta* (non-self) questions whether there is a permanent self to liberate at all, and nirvana is the extinguishing of craving and suffering. Both accept rebirth driven by karma; they differ on what, if anything, is ultimately liberated — a genuine philosophical contrast, not a matter of one being ''right''."},{"heading":"Your turn","text":"Hindu concept, Buddhist concept, or shared? (1) karma, (2) moksha, (3) the Eightfold Path, (4) samsara, (5) Brahman, (6) the Four Noble Truths. Answers: (1) shared, (2) Hindu, (3) Buddhist, (4) shared, (5) Hindu, (6) Buddhist."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming Buddhism is simply ''a branch of Hinduism'' — it is a distinct tradition with its own founder and teachings. Mistake: thinking all Hindus worship in one uniform way; practice varies widely. Exit: (a) The cycle of rebirth in one word? (b) Buddhism''s four core teachings are called the four…? Answers: samsara; Noble Truths."}]}'::jsonb, 'Dharma has related but distinct senses: in Hinduism, sacred duty/order; in Buddhism, the Buddha''s teaching and the nature of reality.', 13),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"The ''emic'' perspective refers to…","options":["an outside analyst''s view","an insider''s own account of their tradition","a statistical survey","an archaeological method"],"answer":1,"explanation":"Emic = insider viewpoint."},{"prompt":"A recurring feature of many Indigenous traditions is that they are…","options":["based on one global scripture","oral and tied to specific land and community","strictly monotheistic worldwide","recently founded"],"answer":1,"explanation":"Typically oral and place-based."},{"prompt":"Karma, samsara, and moksha are concepts most central to…","options":["Shinto","Hinduism","Islam","Confucianism"],"answer":1,"explanation":"Core Hindu concepts, several shared with Buddhism."},{"prompt":"The Four Noble Truths and the Eightfold Path belong to…","options":["Judaism","Daoism","Buddhism","ancient Greek religion"],"answer":2,"explanation":"They frame Buddhist teaching and practice."},{"prompt":"Ancient Greek and Roman religion is best described as…","options":["monotheistic","polytheistic","atheistic","non-ritual"],"answer":1,"explanation":"Many gods honored through temple and festival."},{"prompt":"The academic study of religion is chiefly…","options":["devotional","descriptive and comparative","designed to disprove faith","limited to one tradition"],"answer":1,"explanation":"It describes and compares rather than judging truth."}]}'::jsonb, null, 8),
  (6, 'The Abrahamic religions: Judaism, Christianity, Islam', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Summarize what Judaism, Christianity, and Islam share and where they diverge. Warm-up: what figure gives these three traditions their family name?"},{"heading":"The idea","text":"The three Abrahamic traditions are strictly *monotheistic* and trace their lineage to the patriarch Abraham. *Judaism*, the oldest, centers on a covenant between God and the people of Israel, expressed in the Torah and lived through law (halakha) and practice. *Christianity* grew out of Judaism and centers on Jesus of Nazareth, whom Christians confess as the Christ and, in most traditions, as divine; its scripture adds the New Testament to the Hebrew Bible. *Islam* teaches submission to the one God (Allah), regards Muhammad as the final prophet in a line including Abraham, Moses, and Jesus, and takes the Qur''an as God''s revealed word; practice is anchored by the Five Pillars. All three value scripture, prophecy, prayer, ethics, and community — while disagreeing on pivotal questions such as the identity and role of Jesus."},{"heading":"Worked example","text":"Compare how each views Jesus — a clear case where shared roots yield different conclusions. In Judaism, Jesus is not the messiah and not divine. In Christianity, he is the messiah and, for most, God incarnate whose life and resurrection are central. In Islam, Jesus (Isa) is deeply honored as a prophet and messiah figure, born of the Virgin Mary, but not divine. Describing these side by side is not taking a side; it is mapping where the traditions agree (Jesus mattered) and where they part (who he was)."},{"heading":"Your turn","text":"Judaism, Christianity, or Islam? (1) the Qur''an and the Five Pillars, (2) the Torah and covenant with Israel, (3) the New Testament and the resurrection, (4) Muhammad as final prophet, (5) Jesus confessed as divine, (6) the oldest of the three. Answers: (1) Islam, (2) Judaism, (3) Christianity, (4) Islam, (5) Christianity, (6) Judaism."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming the three worship ''completely different Gods'' — all three are monotheistic and share the Abrahamic lineage, though their theologies differ. Mistake: treating any one as internally uniform; each has many branches. Exit: (a) Islam''s five core practices are called the Five…? (b) Which tradition is the oldest? Answers: Pillars; Judaism."}]}'::jsonb, '''Abrahamic'' groups the three by shared lineage; it does not imply they agree — they differ on central claims.', 13),
  (7, 'East Asian traditions: Confucianism, Daoism, Shinto', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe Confucianism, Daoism, and Shinto and how they function in daily life. Warm-up: two of these three originated in the same country — which country?"},{"heading":"The idea","text":"East Asian traditions often emphasize harmony — social, natural, and cosmic — and are frequently practiced in combination rather than exclusively. *Confucianism*, from the teacher Confucius (Kongzi), is a largely ethical and social tradition stressing virtue (ren, humaneness), ritual propriety (li), and right relationships within family and society; its classic text is the Analects. *Daoism* (Taoism) points to the *Dao* (the Way), an underlying natural order, and values *wu wei* (effortless, non-forcing action) and living in accord with nature; the Dao De Jing is a key text. *Shinto*, indigenous to Japan, honors *kami* — sacred presences in nature, places, and ancestors — through shrine visits, purification, and festivals. Many people in the region engage more than one of these, alongside Buddhism."},{"heading":"Worked example","text":"Compare what each tradition foregrounds. Confucianism asks, ''How should I act toward others to sustain a harmonious society?'' Daoism asks, ''How can I align with the natural flow rather than struggling against it?'' Shinto asks, ''How do we honor the kami and maintain purity and gratitude?'' One leans ethical-social, one cosmological-natural, one ritual and place-centered — and a single person may draw on all three in different moments of life."},{"heading":"Your turn","text":"Confucianism, Daoism, or Shinto? (1) kami and shrine visits, (2) the Analects and filial respect, (3) wu wei and the Dao, (4) ren and li, (5) purification rituals in Japan, (6) the Dao De Jing. Answers: (1) Shinto, (2) Confucianism, (3) Daoism, (4) Confucianism, (5) Shinto, (6) Daoism."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming a person must belong to only one tradition — combining Confucian ethics, Daoist practices, Shinto or Buddhist ritual is common. Mistake: reading Confucianism as worship of many gods; it is chiefly an ethical and social framework. Exit: (a) Sacred presences in Shinto are called…? (b) The Daoist idea of non-forcing action is…? Answers: kami; wu wei."}]}'::jsonb, 'In East Asia people often draw on several traditions at once — these are not always mutually exclusive ''either/or'' religions.', 12),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"monotheism","translation":"belief in a single God","example":"Judaism, Christianity, and Islam are monotheistic traditions."},{"term":"dharma","translation":"in Dharmic traditions, sacred duty and cosmic order (and, in Buddhism, the Buddha''s teaching)","example":"Living according to one''s dharma is a central concern in Hinduism."},{"term":"karma","translation":"the principle that actions have consequences shaping future experience or rebirth","example":"Both Hinduism and Buddhism teach that karma influences rebirth."},{"term":"kami","translation":"in Shinto, sacred presences found in nature, places, and ancestors","example":"Worshippers visit shrines to honor the kami."},{"term":"secularism","translation":"the reduced public authority of religion, or the separation of religion from the state","example":"Rising secularism can change religion''s public role without ending private belief."},{"term":"pluralism","translation":"the peaceful coexistence of many religious traditions within one society","example":"Religious pluralism describes communities where diverse faiths live side by side."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"The three Abrahamic religions share…","options":["belief in many gods","descent traced to Abraham and strict monotheism","the same scripture only","rejection of prophecy"],"answer":1,"explanation":"Shared lineage and monotheism."},{"prompt":"In Islam, the core practices are known as the…","options":["Four Noble Truths","Ten Commandments","Five Pillars","Analects"],"answer":2,"explanation":"The Five Pillars anchor Muslim practice."},{"prompt":"Confucianism is best described as chiefly a tradition of…","options":["polytheistic worship","ethics and social harmony","monastic withdrawal","prophetic revelation"],"answer":1,"explanation":"It stresses virtue and right relationships."},{"prompt":"''Wu wei'', effortless action in accord with nature, belongs to…","options":["Shinto","Daoism","Judaism","Hinduism"],"answer":1,"explanation":"A central Daoist idea."},{"prompt":"Regarding Jesus, Islam holds that he is…","options":["God incarnate","an honored prophet, not divine","the final prophet","unmentioned"],"answer":1,"explanation":"Islam honors Jesus (Isa) as a prophet, not as God."},{"prompt":"A society where many faiths coexist peacefully illustrates…","options":["secularism","pluralism","monotheism","polytheism"],"answer":1,"explanation":"Pluralism is the coexistence of many traditions."}]}'::jsonb, null, 8),
  (10, 'Applied project: respectfully compare two traditions', 'writing', '{"sections":[{"heading":"The task","text":"Choose two traditions from this course and one shared theme — for example, the afterlife, ethics and the good life, sacred texts, ritual and worship, or the nature of the divine. Write a short, respectful comparison that describes how each tradition approaches the theme. Your goal is accurate, neutral description: explain each view fairly, in terms its own adherents would recognize, without ranking them or arguing that one is correct."},{"heading":"Milestones","text":"1) Name your two traditions and your shared theme in one sentence. 2) Describe how the first tradition approaches the theme, using at least one key term correctly. 3) Describe how the second tradition approaches it. 4) State clearly one point where they genuinely agree and one where they genuinely differ. 5) Close by noting the modern context — how might pluralism or secularism shape how these communities encounter each other today?"},{"heading":"Self-check rubric","text":"Accurate: each description is factually correct and would be recognized by adherents (emic-aware). Neutral: you describe without endorsing or disparaging either tradition. Fair: both are given comparable care and detail. Specific: you use at least two key terms from this course correctly. Respectful: your language treats both traditions and their followers with dignity. If all five hold, you have written like a student of comparative religion."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-000000000025' and l.position = v.pos
);
